//! P4-1J (R-RUSTPORT-P4-1J-PLANNED-MARCH-STATE-Q1): zapis i odczyt planow marszu `PlayableState`
//! wzgledem URUCHOMIONEGO kodu pinu `07d2fbd72`.
//!
//! Wektory (blok `BEGIN/END PIN VECTORS` nizej) wygenerowal
//! `dyspozycje/autobot/runs/R-RUSTPORT-P4-1J-PLANNED-MARCH-STATE-Q1/gen-p4-1j-planned-march-vectors.mjs`
//! (wykonuje `planned-march.ts` `plannedMarchesToSave` / `plannedMarchesFromSave` /
//! `validateAutoMarchFromSave`, `main.ts:31124-31130` `syncMarchAttackTarget`, zapis `main.ts:37184`,
//! `:37243-37244` i blok odczytu `main.ts:46272-46287`). Zgodnosc bloku z generatorem: tryb `--check`.
//!
//! * `state_cases`: stan weba -> `JSON.stringify` zapisu -> `JSON.parse` -> odczyt. Rust:
//!   `PlayableState` -> `SaveSnapshot::with_playable_planned_marches` -> JSON -> loader ->
//!   `SaveSnapshot::restore_planned_marches`. Porownanie: zapis Rust == zapis weba odczytany tym samym
//!   loaderem (kolejnosc i wartosci), stan po odczycie == stan weba (cztery mapy), reszta stanu bez zmian.
//! * `raw_cases`: surowy tekst pol zapisu (powtorzone klucze, null, zle typy, legacy `autoMarch`) ->
//!   odczyt. Wpisy, ktorych `PlayableState` nie wyraza (cel nie calkowity / `attackUnitId` spoza
//!   `UnitId`), i pominiety `generalTargetId` musza trafic do raportu, nie zniknac po cichu.
//!
//! Wlasciciel weba `0` (gracz) = `PlayerId(1)` w `PlayableState` (numeracja od 1), `o` -> `o + 1`.

#[path = "../src/domain/events.rs"]
#[allow(dead_code)]
mod events;

#[path = "../src/domain/save_load.rs"]
#[allow(dead_code)]
mod save_load;

#[path = "common/snapshot.rs"]
#[allow(dead_code)]
mod snapshot;

use std::collections::BTreeMap;

use civ_engine::domain::playable::{PlayableMarchStopReason, PlayablePlannedMarch};
use civ_engine::{
    CityDto, CityId, CivilizationDto, GameStateDto, MapDto, PlayableState, PlayableUnit,
    PlayableUnitKind, PlayerId, PositionDto, Rng, TerrainDto, TurnDto, UnitDto, UnitId,
    UnitKindDto,
};
use events::{EventQueue, TurnEvent};
use save_load::{PlannedMarchRestoreReport, SaveSnapshot, TurnPhase};
use serde_json::Value;
use snapshot::decode_snapshot_str;

/// Gracz weba (`ownerId` 0) w numeracji `PlayableState`.
const PLAYER: PlayerId = PlayerId::new(1);

fn vectors() -> Value {
    serde_json::from_str(PIN_VECTORS).expect("wektory JSON")
}

fn valid_state() -> GameStateDto {
    let map = MapDto::new(
        2,
        1,
        vec![
            civ_engine::TileDto::new(PositionDto::new(0, 0), TerrainDto::Plains),
            civ_engine::TileDto::new(PositionDto::new(1, 0), TerrainDto::Hills),
        ],
    )
    .expect("map is valid");
    let civilization = CivilizationDto::new(
        PlayerId::new(1),
        "Rome",
        vec![CityId::new(7)],
        vec![UnitId::new(8)],
    )
    .expect("civilization is valid");
    let city = CityDto::new(
        CityId::new(7),
        PlayerId::new(1),
        "Roma",
        PositionDto::new(0, 0),
        1,
    )
    .expect("city is valid");
    let unit = UnitDto::new(
        UnitId::new(8),
        PlayerId::new(1),
        UnitKindDto::Warrior,
        PositionDto::new(1, 0),
    )
    .expect("unit is valid");
    GameStateDto::new(
        map,
        vec![civilization],
        vec![city],
        vec![unit],
        TurnDto::new(3).expect("turn three is valid"),
    )
    .expect("state is valid")
}

fn snapshot() -> SaveSnapshot {
    let mut queue = EventQueue::new();
    queue.enqueue(3, TurnPhase::Ai, TurnEvent::AiTurn(1));
    SaveSnapshot::new(valid_state(), queue, Rng::new(42))
}

/// Snapshot JSON z polami zapisu weba doklejonymi DOSLOWNIE (kolejnosc kluczy i powtorzenia jak w
/// tekscie; bez przejscia przez `serde_json::Value`, ktory sortuje klucze i scala powtorzenia).
fn wire_snapshot_json(web_save_json: &str) -> String {
    let base = serde_json::to_string(&snapshot()).expect("serializes");
    let body = web_save_json
        .strip_prefix('{')
        .and_then(|s| s.strip_suffix('}'))
        .expect("obiekt zapisu");
    if body.is_empty() {
        return base;
    }
    let head = base.strip_suffix('}').expect("obiekt snapshotu");
    format!("{head},{body}}}")
}

/// Web `generalTargetId` po odczycie: niepusty napis, pusty/brak/`null` = `None` (`planned-march.ts:471-472`).
fn general_of(dest: &Value) -> Option<String> {
    dest.get("generalTargetId")
        .and_then(Value::as_str)
        .filter(|id| !id.is_empty())
        .map(str::to_owned)
}

/// Kanoniczny zapis dziesietny `UnitId` (wyrocznia testu; web trzyma id jako napis).
fn canonical_id(text: &str) -> Option<UnitId> {
    let value = text.parse::<u64>().ok()?;
    (value.to_string() == text).then_some(UnitId::new(value))
}

fn id_of(value: &Value) -> UnitId {
    canonical_id(value.as_str().expect("id napisem")).expect("kanoniczne id jednostki")
}

/// Liczba JSON calkowita w zakresie `i32`.
fn int_of(value: &Value) -> Option<i32> {
    value.as_i64().and_then(|v| i32::try_from(v).ok())
}

fn units_of(case: &Value) -> Vec<PlayableUnit> {
    case["units"]
        .as_array()
        .expect("units")
        .iter()
        .map(|unit| {
            let owner = unit["ownerId"].as_u64().expect("ownerId");
            let q = u16::try_from(unit["q"].as_u64().expect("q")).expect("q u16");
            let r = u16::try_from(unit["r"].as_u64().expect("r")).expect("r u16");
            PlayableUnit {
                id: id_of(&unit["id"]),
                owner_id: PlayerId::new(owner + 1),
                kind: PlayableUnitKind::Warrior,
                position: PositionDto::new(q, r),
                movement: 1,
                movement_max: 1,
                selected: false,
            }
        })
        .collect()
}

fn pairs(value: &Value) -> &Vec<Value> {
    value.as_array().expect("lista par")
}

fn reason_of(value: &Value) -> PlayableMarchStopReason {
    serde_json::from_value(value.clone()).expect("powod zatrzymania weba = wariant serde")
}

/// Stan weba (cztery mapy) jako pola `PlayableState`; plany stanu sa zawsze wyrazalne.
fn state_of(case: &Value) -> PlayableState {
    let mut state = PlayableState::empty();
    state.units = units_of(case);
    for pair in pairs(&case["plannedMarches"]) {
        let dest = &pair[1];
        state.planned_marches.push(PlayablePlannedMarch {
            unit_id: id_of(&pair[0]),
            dest_q: int_of(&dest["destQ"]).expect("destQ stanu"),
            dest_r: int_of(&dest["destR"]).expect("destR stanu"),
            attack_unit_id: dest.get("attackUnitId").map(id_of),
            general_target_id: general_of(dest),
        });
    }
    for pair in pairs(&case["marchStopNotified"]) {
        state
            .march_stop_notified
            .insert(id_of(&pair[0]), reason_of(&pair[1]));
    }
    for pair in pairs(&case["marchStopDetail"]) {
        state.march_stop_detail.insert(
            id_of(&pair[0]),
            pair[1].as_str().expect("detail").to_owned(),
        );
    }
    for pair in pairs(&case["marchAttackTargets"]) {
        state
            .march_attack_targets
            .insert(id_of(&pair[0]), id_of(&pair[1]));
    }
    state
}

/// Oczekiwany stan Rust po odczycie z wyniku weba `loaded` + oczekiwany raport pominiec.
fn expected_after_load(
    before: &PlayableState,
    loaded: &Value,
) -> (PlayableState, PlannedMarchRestoreReport) {
    let mut expected = before.clone();
    expected.planned_marches.clear();
    expected.march_attack_targets.clear();
    expected.march_stop_notified.clear();
    expected.march_stop_detail.clear();
    let mut report = PlannedMarchRestoreReport::default();
    let mut representable: Vec<String> = Vec::new();
    for pair in pairs(&loaded["plannedMarches"]) {
        let uid = pair[0].as_str().expect("uid").to_owned();
        let dest = &pair[1];
        let attack = match dest.get("attackUnitId") {
            None => Some(None),
            Some(text) => canonical_id(text.as_str().expect("attackUnitId napisem")).map(Some),
        };
        match (
            canonical_id(&uid),
            int_of(&dest["destQ"]),
            int_of(&dest["destR"]),
            attack,
        ) {
            (Some(unit_id), Some(dest_q), Some(dest_r), Some(attack_unit_id)) => {
                expected.planned_marches.push(PlayablePlannedMarch {
                    unit_id,
                    dest_q,
                    dest_r,
                    attack_unit_id,
                    general_target_id: general_of(dest),
                });
                representable.push(uid);
            }
            _ => report.unrepresentable.push(uid),
        }
    }
    for pair in pairs(&loaded["marchAttackTargets"]) {
        let uid = pair[0].as_str().expect("uid");
        if representable.iter().any(|kept| kept == uid) {
            expected
                .march_attack_targets
                .insert(id_of(&pair[0]), id_of(&pair[1]));
        }
    }
    assert!(
        pairs(&loaded["marchStopNotified"]).is_empty(),
        "web czysci marchStopNotified"
    );
    assert!(
        pairs(&loaded["marchStopDetail"]).is_empty(),
        "web czysci marchStopDetail"
    );
    (expected, report)
}

#[test]
fn pin_vectors_header_and_counts() {
    let v = vectors();
    assert_eq!(v["pin"], "07d2fbd72f758705f8e1d59cc4968027ffbafe75");
    assert_eq!(v["sources"]["main.ts"][2], "load:main.ts:46272-46287");
    assert_eq!(pairs(&v["state_cases"]).len(), 67);
    assert_eq!(pairs(&v["raw_cases"]).len(), 78);
}

#[test]
fn state_cases_save_and_load_like_web() {
    let v = vectors();
    let (mut saved_nonempty, mut filtered, mut attacks, mut reordered) = (0, 0, 0, 0);
    for case in pairs(&v["state_cases"]) {
        let name = case["name"].as_str().expect("name");
        let state = state_of(case);
        let save_text = case["saveText"].as_str().expect("saveText");

        // Zapis: Rust == zapis weba odczytany tym samym loaderem (kolejnosc, liczby, autoMarch).
        let ours = snapshot().with_playable_planned_marches(&state);
        let web = decode_snapshot_str(&wire_snapshot_json(save_text)).expect("zapis weba");
        assert_eq!(ours.planned_marches(), web.planned_marches(), "{name}");
        assert_eq!(ours.auto_march(), web.auto_march(), "{name}");
        let encoded = serde_json::to_string(&ours).expect("serializes");
        if save_text == "{}" {
            assert_eq!(
                encoded,
                serde_json::to_string(&snapshot()).expect("serializes"),
                "{name}: pusty plan = zapis bajtowo bez zmian"
            );
        } else {
            saved_nonempty += 1;
        }

        // Odczyt wlasnego zapisu: stan == stan weba po odczycie, reszta stanu bez zmian.
        let decoded = decode_snapshot_str(&encoded).expect("wlasny zapis");
        assert_eq!(decoded.planned_marches(), ours.planned_marches(), "{name}");
        assert_eq!(decoded.auto_march(), ours.auto_march(), "{name}");
        let mut loaded = state.clone();
        let report = decoded.restore_planned_marches(&mut loaded, PLAYER);
        let (expected, expected_report) = expected_after_load(&state, &case["loaded"]);
        assert_eq!(loaded, expected, "{name}");
        assert_eq!(report, expected_report, "{name}");
        assert_eq!(
            report,
            PlannedMarchRestoreReport::default(),
            "{name}: stan zapisany przez Rust jest w calosci wyrazalny"
        );

        if loaded.planned_marches.len() < state.planned_marches.len() {
            filtered += 1;
        }
        attacks += loaded.march_attack_targets.len();
        // Kolejnosc po odczycie (klucze obiektu) rozna od kolejnosci `Map` stanu dla tych samych id.
        let after: Vec<UnitId> = loaded.planned_marches.iter().map(|m| m.unit_id).collect();
        let before: Vec<UnitId> = state
            .planned_marches
            .iter()
            .map(|m| m.unit_id)
            .filter(|id| after.contains(id))
            .collect();
        if after != before {
            reordered += 1;
        }
    }
    // Pokrycie galezi: zapisy niepuste, filtr przy odczycie, cele ataku, zmiana kolejnosci kluczy.
    eprintln!(
        "state: niepuste={saved_nonempty} filtr={filtered} ataki={attacks} kolejnosc={reordered}"
    );
    assert!(saved_nonempty >= 60, "niepuste zapisy: {saved_nonempty}");
    assert!(filtered >= 50, "odfiltrowane przy odczycie: {filtered}");
    assert!(attacks >= 25, "cele ataku po odczycie: {attacks}");
    assert!(reordered >= 15, "kolejnosc kluczy obiektu: {reordered}");
}

#[test]
fn raw_cases_load_like_web_with_explicit_report() {
    let v = vectors();
    let (mut loaded_any, mut unrepresentable, mut general_kept, mut attacks) = (0, 0, 0, 0);
    for case in pairs(&v["raw_cases"]) {
        let name = case["name"].as_str().expect("name");
        let raw = case["rawSave"].as_str().expect("rawSave");
        // Stan przed odczytem z "brudnymi" mapami (jak generator): odczyt musi je wyczyscic.
        let mut before = PlayableState::empty();
        before.units = units_of(case);
        before.planned_marches.push(PlayablePlannedMarch {
            unit_id: UnitId::new(1),
            dest_q: 9,
            dest_r: 9,
            attack_unit_id: None,
            general_target_id: None,
        });
        before
            .march_stop_notified
            .insert(UnitId::new(1), PlayableMarchStopReason::Obstacle);
        before
            .march_stop_detail
            .insert(UnitId::new(1), "zablokowany heks na trasie".to_owned());
        before
            .march_attack_targets
            .insert(UnitId::new(1), UnitId::new(2));

        let decoded = decode_snapshot_str(&wire_snapshot_json(raw)).expect("zapis weba");
        let mut loaded = before.clone();
        let report = decoded.restore_planned_marches(&mut loaded, PLAYER);
        let (expected, expected_report) = expected_after_load(&before, &case["loaded"]);
        assert_eq!(loaded, expected, "{name}: {raw}");
        assert_eq!(report, expected_report, "{name}: {raw}");

        if !loaded.planned_marches.is_empty() {
            loaded_any += 1;
        }
        unrepresentable += report.unrepresentable.len();
        general_kept += loaded
            .planned_marches
            .iter()
            .filter(|march| march.general_target_id.is_some())
            .count();
        attacks += loaded.march_attack_targets.len();
    }
    eprintln!(
        "raw: wczytane={loaded_any} niewyrazalne={unrepresentable} general={general_kept} ataki={attacks}"
    );
    assert!(
        loaded_any >= 30,
        "przypadki z wczytanym planem: {loaded_any}"
    );
    assert!(
        unrepresentable >= 5,
        "wpisy niewyrazalne: {unrepresentable}"
    );
    assert!(
        general_kept >= 5,
        "zachowane generalTargetId po odczycie: {general_kept}"
    );
    assert!(attacks >= 5, "cele ataku: {attacks}");
}

/// Twarde oczekiwania przypadku z odchyleniem (bez wyroczni testu): web trzyma ulamek i
/// `attackUnitId` spoza `UnitId`, Rust pomija je jawnie w raporcie.
#[test]
fn raw_deviation_case_is_reported_by_name() {
    let v = vectors();
    let case = pairs(&v["raw_cases"])
        .iter()
        .find(|c| c["name"].as_str().is_some_and(|n| n.starts_with("ulamek")))
        .expect("przypadek z ulamkiem");
    let decoded = decode_snapshot_str(&wire_snapshot_json(case["rawSave"].as_str().expect("raw")))
        .expect("zapis");
    let mut state = PlayableState::empty();
    state.units = units_of(case);
    let report = decoded.restore_planned_marches(&mut state, PLAYER);
    assert_eq!(report.unrepresentable, vec!["2", "3", "7"]);
    let web_general = pairs(&case["loaded"]["plannedMarches"])
        .iter()
        .find(|pair| pair[0].as_str() == Some("12"))
        .map(|pair| general_of(&pair[1]))
        .expect("wpis 12 w wyniku weba");
    assert_eq!(
        state.planned_marches,
        vec![PlayablePlannedMarch {
            unit_id: UnitId::new(12),
            dest_q: 1,
            dest_r: 1,
            attack_unit_id: None,
            general_target_id: web_general,
        }]
    );
    assert_eq!(state.march_attack_targets, BTreeMap::new());
    // Web po odczycie trzyma wszystkie cztery wpisy i dwa cele ataku (dowod z wektora).
    assert_eq!(pairs(&case["loaded"]["plannedMarches"]).len(), 4);
    assert_eq!(pairs(&case["loaded"]["marchAttackTargets"]).len(), 2);
}

